import{_ as r,o as t,c as n,a2 as p}from"./chunks/framework.B2QVIpOM.js";const u=JSON.parse('{"title":"福建中学 · 年份未注明 · 中三 · 考试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"fukien","school_zh":"福建中学","school_en":"Fukien Secondary School","grade":"s3","year":"unknown","year_label":"年份未注明","type":"written","title":"福建中学 · 年份未注明 · 中三 · 考试","anonymous":true,"source_ids":["M194","X186","X187","X189"],"rounds":["r2","r1","unknown"]},"headers":[],"relativePath":"reports/fukien/s3/unknown-written.md","filePath":"reports/fukien/s3/unknown-written.md"}'),s={name:"reports/fukien/s3/unknown-written.md"};function e(a,o,g,l,c,i){return t(),n("div",null,[...o[0]||(o[0]=[p('<h1 id="福建中学-·-年份未注明-·-中三-·-考试" tabindex="-1">福建中学 · 年份未注明 · 中三 · 考试 <a class="header-anchor" href="#福建中学-·-年份未注明-·-中三-·-考试" aria-label="Permalink to &quot;福建中学 · 年份未注明 · 中三 · 考试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/fukien">← 返回福建中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-m194" tabindex="-1">资料来源：福建中学中三春季插班考情.pdf <a class="header-anchor" href="#record-m194" aria-label="Permalink to &quot;资料来源：福建中学中三春季插班考情.pdf {#record-m194}&quot;">​</a></h2><p><strong>资料类型：</strong> 考试反馈</p><p><strong>入学途径：</strong> 插班</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第二轮-·-模式推定" tabindex="-1">第二轮 · 模式推定 <a class="header-anchor" href="#第二轮-·-模式推定" aria-label="Permalink to &quot;第二轮 · 模式推定&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong> 语言未注明</p><p><strong>考试日期与报到</strong></p><p>分享者转述一位考生在6月中旬参加插班中三笔试的经历。考生8时15分到场报到，9时正式开考，在考场等了约40分钟；分享者据此提醒应预留报到时间。</p><p><strong>各科时长与休息</strong></p><p>语文、数学及英语各考1小时，科目之间约有15分钟休息。</p><p><strong>整体感受与试卷语言</strong></p><p>反馈认为整体题量较大，试卷的语言选择对内地插班生较友好。原文将语文及数学的简体、繁体和英文版本合并描述，未逐科说明，不据此确认语文有英文版本。</p></blockquote><blockquote><p><strong>语文：</strong> 简体中文（原文另提其他版本，适用科目待核实）</p><p><strong>题型与题量</strong></p><p>题型包括选择、简答、现代文阅读、古文及一篇200字作文。</p><p><strong>阅读要求与评价</strong></p><p>反馈认为现代文较简单，主要考内容理解、概括及个人观点表达；古文要求翻译词语和句子意思，若能读懂文章，考生认为难度不大。</p><p><strong>写作与完成情况</strong></p><p>作文要求写一次学习新事物的经历及感受。该考生提前20分钟完成语文，认为整体不难。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>题量与整体感受</strong></p><p>反馈认为英语是三科中最难、题量最大的一科，仅答题纸就有13页，题型为选择及简答，没有作文。</p><p><strong>整理者的备考判断</strong></p><p>分享者认为词汇量要求很高、需要长期积累，甚至以“在内地英语能否考满分”作为个人报考建议的参照；这并非学校报名条件或分数线。</p><p><strong>诗歌鉴赏</strong></p><p>先考诗歌鉴赏，包括韵脚、同义词、手法分析、诗句意思解释及个人理解。</p><p><strong>阅读理解</strong></p><p>阅读理解有2篇，资料记为5至6段，每篇后面的问题较多，需要反复阅读以提炼信息。</p><p><strong>语言运用题</strong></p><p>另有完形填空10题、改写句子10至15句、修改句子10句、选词填空16选8。</p><p><strong>完成情况</strong></p><p>考生差1题未完成，考后明显感到沮丧。</p></blockquote><blockquote><p><strong>数学：</strong> 简体中文／繁体中文／英语可选</p><p><strong>题型与难度感受</strong></p><p>反馈认为数学比英语简单很多，同样包含选择及简答题。</p><p><strong>题目内容</strong></p><p>前面约十几至二十道简答题相对容易，考点包括比例尺、相似三角形、因式分解、三角函数、二元一次方程。</p><p><strong>后段题目</strong></p><p>最后几题较复杂，但可列方程解决。</p><p><strong>辅助计算与完成情况</strong></p><p>可借助计算设备辅助作答（原文称“计算机”，未进一步说明设备类型）；尽管计算量较大，反馈认为仍能应付，可以提前完成。</p></blockquote><h2 id="record-x186" tabindex="-1">资料来源：【置顶】最终汇总版本学校考情_0727更新版.xlsx <a class="header-anchor" href="#record-x186" aria-label="Permalink to &quot;资料来源：【置顶】最终汇总版本学校考情_0727更新版.xlsx {#record-x186}&quot;">​</a></h2><p><strong>资料类型：</strong> 考试反馈</p><p><strong>入学途径：</strong> 未注明</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>英语：</strong> 英语</p><p><strong>考试安排</strong></p><p>该份反馈对应中二升中三，记载3月7日参加第一轮；反馈者预计通过后会有第二轮。语文、数学、英语每科15题，各20分钟，合计1小时。</p><p><strong>英语题型</strong></p><p>英语包含2篇阅读及1篇语法题，全部为选择题，没有简答题。阅读以细节题为主，也考词汇。</p><p><strong>考生的难度比较</strong></p><p>考生认为首轮较简单，选择题作答较快。反馈将试题与课堂使用的OEF 3A单元测试卷3AU1 set1／set2比较，认为考试阅读简单很多；两篇文章的篇幅估计约为课堂练习的三分之二。</p></blockquote><h2 id="record-x187" tabindex="-1">资料来源：【置顶】最终汇总版本学校考情_0727更新版.xlsx <a class="header-anchor" href="#record-x187" aria-label="Permalink to &quot;资料来源：【置顶】最终汇总版本学校考情_0727更新版.xlsx {#record-x187}&quot;">​</a></h2><p><strong>资料类型：</strong> 考试反馈</p><p><strong>入学途径：</strong> 未注明</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>英语：</strong> 英语</p><p><strong>阅读内容与题量</strong></p><p>考试1小时，包含2篇香港常见题型的阅读理解：第一篇约15题，第二篇占2页、约20题，简答题较多。</p><p><strong>文法题</strong></p><p>文法题量较大，包括词语填空、完形填空及改错（proofreading）。</p></blockquote><blockquote><p><strong>语文／数学：</strong> 简体中文</p><p><strong>试卷文字与感受</strong></p><p>语文及数学试卷使用简体字，反馈者认为对内地学生较友好。</p></blockquote><h2 id="record-x189" tabindex="-1">资料来源：【置顶】最终汇总版本学校考情_0727更新版.xlsx <a class="header-anchor" href="#record-x189" aria-label="Permalink to &quot;资料来源：【置顶】最终汇总版本学校考情_0727更新版.xlsx {#record-x189}&quot;">​</a></h2><p><strong>资料类型：</strong> 考试反馈</p><p><strong>入学途径：</strong> 未注明</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="轮次未注明-·-请以当次考试通知为准" tabindex="-1">轮次未注明 · 请以当次考试通知为准 <a class="header-anchor" href="#轮次未注明-·-请以当次考试通知为准" aria-label="Permalink to &quot;轮次未注明 · 请以当次考试通知为准&quot;">​</a></h3><blockquote><p><strong>数学：</strong> 中文（简繁未注明）</p><p><strong>范围与作答感受</strong></p><p>一般香港数学内容，45分钟。反馈者认为数学难度较大、题量大、作答时间短，尤其把最后两道题的难度比作中考压轴题或竞赛题。</p><p><strong>录取记录</strong></p><p>总表另标注该考生未录取，未说明具体原因。</p></blockquote>',31)])])}const h=r(s,[["render",e]]);export{u as __pageData,h as default};
